// Coordinated regular switches on whole graph (root can change role). Optimize forbidden blue-nine count by exact switch delta: lost/gained nines contain exactly one of the two newly red / previously red pairs. A nine cannot contain both counted pairs since the other matching is red. Track incumbent and explore modest uphill moves.
use std::io::{self,Read};type G=[u64;35];const F:u64=(1<<35)-1;fn cnt(g:&G,mut p:u64,k:u32)->i32{if k==1{return p.count_ones()as i32}let mut ans=0;while p.count_ones()>=k{let i=p.trailing_zeros()as usize;p&=p-1;ans+=cnt(g,p&!g[i],k-1)}ans}fn pair(g:&G,i:usize,j:usize)->i32{cnt(g,F&!(1<<i|1<<j|g[i]|g[j]),7)}fn sw(g:&mut G,i:usize,j:usize){g[i]^=1<<j;g[j]^=1<<i}fn rng(x:&mut u64)->u64{*x^=*x<<13;*x^=*x>>7;*x^=*x<<17;*x}fn edges(g:&G)->Vec<(usize,usize)>{(0..35).flat_map(|i|(0..i).filter(move|&j|g[i]>>j&1!=0).map(move|j|(i,j))).collect()}
fn main(){let args:Vec<_>=std::env::args().collect();let mut st=args[1].parse().unwrap();let rest=args[2].parse::<usize>().unwrap();let mut text=String::new();io::stdin().read_to_string(&mut text).unwrap();let mut orig=[0;35];orig.copy_from_slice(&text.split_whitespace().map(|v|v.parse().unwrap()).collect::<Vec<_>>());let mut champ=orig;let mut best=cnt(&orig,F,9);let mut accepted=0;for rep in 0..rest{let mut g=if rep%11==10{orig}else{champ};let mut e=edges(&g);let mut cost=cnt(&g,F,9);for j in 0..30000{let x=rng(&mut st)as usize%e.len();let y=rng(&mut st)as usize%e.len();let(a,b)=e[x];let(mut c,mut d)=e[y];if rng(&mut st)&1!=0{std::mem::swap(&mut c,&mut d)}if a==c||a==d||b==c||b==d||g[a]>>c&1!=0||g[b]>>d&1!=0{continue}let ab=1<<b;let dc=1<<d;if (g[a]&g[c]&!(ab|dc))!=0||(g[b]&g[d]&!(1<<a|1<<c))!=0{continue}let lost=pair(&g,a,c)+pair(&g,b,d);sw(&mut g,a,b);sw(&mut g,c,d);sw(&mut g,a,c);sw(&mut g,b,d);let delta=pair(&g,a,b)+pair(&g,c,d)-lost;let temp=0.3+(2.+(rep%12)as f64*1.2)*(1.-j as f64/30000.).powi(2);if delta<=0||((rng(&mut st)>>11)as f64)/((1u64<<53)as f64)<(-(delta as f64)/temp).exp(){accepted+=1;cost+=delta;e[x]=(a,c);e[y]=(b,d);if cost<best{assert_eq!(cnt(&g,F,9),cost);best=cost;champ=g;if best==0{break}}}else{sw(&mut g,a,b);sw(&mut g,c,d);sw(&mut g,a,c);sw(&mut g,b,d)}}if best==0{break}}println!("{};{};{}",best,accepted,champ.iter().map(|v|v.to_string()).collect::<Vec<_>>().join(" "))}
